/**
 * Order coordinator: a two-service saga (ledger hold/capture, fulfilment shipment) with compensation.
 * See specification.md for the full contract and conformance/cases.mjs for exactly what is checked.
 */

const RETRY_DELAY_MS = 10;
const MAX_ATTEMPTS = 4;

export class ValidationError extends Error {
	constructor(message, fields) {
		super(message);
		this.name = "ValidationError";
		this.fields = fields;
	}
}

export class ServiceError extends Error {
	constructor(message, status, code) {
		super(message);
		this.name = "ServiceError";
		this.status = status;
		this.code = code;
	}
}

function isSuccess(response) {
	return response.status >= 200 && response.status < 300;
}

function isRetryableStatus(status) {
	return status >= 500 && status < 600;
}

function toError(response) {
	const error = response.body?.error ?? {};
	const message = error.message ?? `request failed with status ${response.status}`;
	if (error.code === "validation_failed") {
		return new ValidationError(message, error.fields ?? []);
	}
	return new ServiceError(message, response.status, error.code);
}

// Always dereference `service.request` at call time -- never capture the method once at construction. Some
// conformance cases replace a service's `request` property after the coordinator is built to inject a failure,
// and a reference captured up front would keep calling the ORIGINAL function and silently miss the wrapper.
async function callWithRetry(service, method, path, options, sleep) {
	let response;
	for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
		response = service.request(method, path, options);
		if (isRetryableStatus(response.status) && attempt < MAX_ATTEMPTS) {
			await sleep(RETRY_DELAY_MS);
			continue;
		}
		break;
	}
	return response;
}

export function createOrderCoordinator({ ledger, fulfilment, sleep }) {
	async function releaseHold(holdId) {
		return callWithRetry(ledger, "POST", `/holds/${holdId}/release`, { headers: {} }, sleep);
	}

	async function placeOrder({ orderId, amountMinor, sku }) {
		const idempotencyKey = `order:${orderId}`;

		// 1. Hold the money first. If it cannot be created, fail -- and do not touch fulfilment.
		const holdResponse = await callWithRetry(
			ledger,
			"POST",
			"/holds",
			{ headers: { "idempotency-key": idempotencyKey }, body: { amountMinor } },
			sleep,
		);
		if (!isSuccess(holdResponse)) {
			throw toError(holdResponse);
		}
		const hold = holdResponse.body;

		// 2. Then book the shipment.
		const shipmentResponse = await callWithRetry(
			fulfilment,
			"POST",
			"/shipments",
			{ headers: { "idempotency-key": idempotencyKey }, body: { sku } },
			sleep,
		);
		if (!isSuccess(shipmentResponse)) {
			// 3. The shipment failed: release the hold, then reject with the ORIGINAL failure -- the caller needs
			// to know why the order failed, not that a compensation ran.
			const originalError = toError(shipmentResponse);
			const releaseResponse = await releaseHold(hold.id);
			if (!isSuccess(releaseResponse)) {
				// The compensation itself did not go through even after retries -- fail loudly about THAT rather
				// than quietly reporting the original failure as if the saga had cleanly unwound, when the hold
				// may still be standing.
				const releaseError = toError(releaseResponse);
				throw new ServiceError(
					`order rejected (${originalError.message}) and the compensating release also failed: ${releaseError.message}`,
					releaseResponse.status,
					releaseResponse.body?.error?.code ?? "release_failed",
				);
			}
			throw originalError;
		}
		const shipment = shipmentResponse.body;

		// 4. Then capture. Once a capture has been ATTEMPTED, never release: a 5xx here is not a "no" -- the
		// ledger may already hold the money as captured, and releasing it would refund money already taken.
		const captureResponse = await callWithRetry(
			ledger,
			"POST",
			`/holds/${hold.id}/capture`,
			{ headers: {} },
			sleep,
		);
		if (!isSuccess(captureResponse)) {
			throw toError(captureResponse);
		}

		return { hold: captureResponse.body, shipment };
	}

	return { placeOrder };
}
